def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    rounds_left = 100 - n
    if rounds_left <= 0:
        return 'D'
    if rounds_left == 1:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    rate_d = opp_d / float(n)
    last_my, last_opp = my[-1], opp[-1]

    last5 = opp[-5:]
    last10 = opp[-10:]

    last5_d = sum(1 for x in last5 if x == 'D')
    last10_d = sum(1 for x in last10 if x == 'D')
    recent3_c = sum(1 for x in opp[-3:] if x == 'C')
    recent5_c = sum(1 for x in last5 if x == 'C')

    cd_streak = 0
    for a, b in reversed(history):
        if b == 'D' and a == 'C':
            cd_streak += 1
        else:
            break

    after_D_total = 0
    after_D_c = 0
    for i in range(n - 1):
        if my[i] == 'D':
            after_D_total += 1
            if opp[i + 1] == 'C':
                after_D_c += 1

    exploitable = False
    retaliatory = False

    if after_D_total >= 2:
        if after_D_c * 2 >= after_D_total:
            exploitable = True
        if after_D_c * 10 <= after_D_total * 3:
            retaliatory = True
    elif after_D_total == 1:
        if after_D_c == 1 and rate_d < 0.45 and recent3_c >= 3:
            exploitable = True
        if after_D_c == 0 and rate_d < 0.35:
            retaliatory = True

    hostile = False
    if len(last5) == 5 and last5_d == 5:
        hostile = True
    if cd_streak >= 6:
        hostile = True
    if len(last10) == 10 and last10_d >= 8:
        hostile = True
    if n >= 6 and opp_d >= 6 and rate_d > 0.6:
        hostile = True

    if rounds_left == 2:
        if hostile or opp_d == 0 or (exploitable and rate_d < 0.55):
            return 'D'
        if retaliatory or rate_d < 0.12:
            return 'C'
        if last_opp == 'D':
            return 'C'
        if rate_d < 0.3:
            return 'C'
        return 'D'

    if opp_d == 0:
        if my_d > 0:
            return 'D' if rng.random() < 0.95 else 'C'
        if n < 12:
            return 'C'
        if n < 20:
            return 'D' if rng.random() < 0.10 else 'C'
        return 'D' if rng.random() < 0.35 else 'C'

    if last_opp == 'D':
        if hostile:
            return 'D'

        if n <= 5 and opp_d <= 4 and cd_streak < 4:
            return 'C' if rng.random() < 0.9 else 'D'

        if cd_streak == 4:
            return 'D' if rng.random() < 0.55 else 'C'

        if retaliatory and cd_streak <= 2 and rate_d < 0.4:
            return 'C' if rng.random() < 0.9 else 'D'

        if last_my == 'D':
            if retaliatory and rate_d < 0.5:
                return 'C'
            if rate_d < 0.2:
                return 'C' if rng.random() < 0.85 else 'D'
            if rate_d < 0.35:
                return 'C' if rng.random() < 0.65 else 'D'
            if rate_d < 0.5:
                return 'C' if rng.random() < 0.35 else 'D'
            return 'D'

        if cd_streak >= 6:
            return 'D' if rng.random() < 0.85 else 'C'
        if rate_d < 0.3:
            return 'C' if rng.random() < 0.95 else 'D'
        if rate_d < 0.45:
            if cd_streak <= 2:
                return 'D' if rng.random() < 0.45 else 'C'
            if cd_streak <= 4 and recent5_c >= 2:
                return 'C' if rng.random() < 0.65 else 'D'
            return 'D' if rng.random() < 0.75 else 'C'
        if rate_d < 0.6:
            return 'D' if rng.random() < 0.75 else 'C'
        return 'D'

    if last_opp == 'C':
        if last_my == 'D':
            if exploitable and rate_d < 0.55:
                return 'D' if rng.random() < 0.65 else 'C'
            if retaliatory:
                return 'C'
            if rate_d < 0.12 and recent5_c >= 5 and n > 20:
                return 'D' if rng.random() < 0.2 else 'C'
            return 'C'

        if exploitable:
            if rate_d < 0.55:
                if recent5_c >= 4 and rounds_left > 8:
                    return 'D' if rng.random() < 0.55 else 'C'
                return 'D' if rng.random() < 0.35 else 'C'
            return 'D' if rng.random() < 0.2 else 'C'

        if rate_d < 0.12 and recent5_c >= 5 and n >= 16:
            return 'D' if rng.random() < 0.08 else 'C'

        if rate_d < 0.45 and recent5_c >= 3 and last10_d <= 5 and n >= 20:
            return 'D' if rng.random() < 0.12 else 'C'

        if rate_d >= 0.45:
            if recent5_c >= 3 and rate_d < 0.6:
                return 'D' if rng.random() < 0.4 else 'C'
            return 'D' if rng.random() < 0.7 else 'C'

        return 'C'

    return 'C'
